package pe.nexo.store.order;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.nexo.store.order.dto.*;import pe.nexo.store.product.*;import java.math.*;import java.util.*;
@Service public class OrderService{private final OrderRepository orders;private final ProductService products;public OrderService(OrderRepository orders,ProductService products){this.orders=orders;this.products=products;}@Transactional public OrderResponse create(CreateOrderRequest request){Map<Long,Integer>quantities=new LinkedHashMap<>();for(OrderItemRequest line:request.items())quantities.merge(line.productId(),line.quantity(),Integer::sum);List<OrderItem>items=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO;for(var line:quantities.entrySet()){Product p=products.findForOrder(line.getKey());p.reserve(line.getValue());items.add(new OrderItem(p.getId(),p.getName(),line.getValue(),p.getPrice()));subtotal=subtotal.add(p.getPrice().multiply(BigDecimal.valueOf(line.getValue())));}BigDecimal discount="NEXO10".equalsIgnoreCase(request.couponCode())?subtotal.multiply(new BigDecimal("0.10")):BigDecimal.ZERO;BigDecimal total=subtotal.subtract(discount).setScale(2,RoundingMode.HALF_UP);CustomerOrder order=new CustomerOrder("NX-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),request.customerName().trim(),request.email().trim().toLowerCase(Locale.ROOT),request.phone().trim(),request.address().trim(),request.city().trim(),request.paymentMethod().trim(),request.couponCode(),subtotal,discount,total);items.forEach(order::addItem);return OrderResponse.from(orders.save(order));}public OrderResponse findByNumber(String n){return OrderResponse.from(orders.findByOrderNumber(n).orElseThrow(()->new IllegalArgumentException("Pedido no encontrado")));}public CustomerOrder findById(Long id){return orders.findById(id).orElseThrow(()->new IllegalArgumentException("Pedido no encontrado"));}public List<CustomerOrder>findAll(){return orders.findAll();}@Transactional public CustomerOrder changeStatus(Long id,OrderStatus status){CustomerOrder order=findById(id);order.changeStatus(status);return order;}}
